namespace Kaff.Api.Features.DailyLogs.CorrectDayLabour;

/// <summary>The hours the saved entry should read, not the difference: the server stores the difference as a signed delta.</summary>
/// <param name="CorrectionId">Generated by the device, so a retried request is recognised and not applied twice.</param>
/// <param name="Hours">The corrected hours. Above 0, at most 16, in half-hour steps.</param>
public sealed record Request(Guid? CorrectionId, decimal Hours);
